from PySide6 import QtCore, QtWidgets
from PySide6.QtCore import Qt
from PySide6.QtGui import QIcon
from PySide6.QtWidgets import QDialog

from videotrans.configure.config import tr, settings, params, ROOT_DIR
from videotrans.util.help_misc import open_url


class Ui_openllm(QDialog):
    def __init__(self):
        super().__init__()
        self.setWindowIcon(QIcon(f"{ROOT_DIR}/videotrans/styles/icon.ico"))
        self.setupUi(self)
    def setupUi(self, form):
        self.has_done = False
        form.setObjectName("form")
        form.resize(600, 600)

        v1 = QtWidgets.QVBoxLayout(form)

        h_url = QtWidgets.QHBoxLayout()
        h3 = QtWidgets.QHBoxLayout()
        h4 = QtWidgets.QHBoxLayout()

        self.label_0 = QtWidgets.QPushButton()
        self.label_0.setGeometry(QtCore.QRect(10, 10, 580, 35))
        self.label_0.setStyleSheet("background-color: rgba(255, 255, 255,0);text-align:left")
        self.label_0.setCursor(Qt.PointingHandCursor)
        self.label_0.setText('OpenLLM - ' + tr('OpenAI-compatible endpoint for your API keys, subscription accounts and local models. Use the cloud URL with a key, or a local daemon URL without one'))
        self.label_0.clicked.connect(lambda: open_url(url='https://docs.openllm.sh'))
        v1.addWidget(self.label_0)

        self.label_url = QtWidgets.QLabel()
        self.label_url.setObjectName("label_url")
        self.openllm_api = QtWidgets.QLineEdit()
        self.openllm_api.setMinimumSize(QtCore.QSize(0, 35))
        self.openllm_api.setObjectName("openllm_api")
        self.openllm_api.setPlaceholderText('https://www.openllm.sh/v1')
        h_url.addWidget(self.label_url)
        h_url.addWidget(self.openllm_api)
        v1.addLayout(h_url)

        self.label_3 = QtWidgets.QLabel()
        self.label_3.setObjectName("label_3")
        self.openllm_key = QtWidgets.QLineEdit()
        self.openllm_key.setMinimumSize(QtCore.QSize(0, 35))
        self.openllm_key.setObjectName("openllm_key")
        h3.addWidget(self.label_3)
        h3.addWidget(self.openllm_key)
        v1.addLayout(h3)

        h_token = QtWidgets.QHBoxLayout()

        label_token = QtWidgets.QLabel()
        label_token.setObjectName("label_token")
        label_token.setText(tr("Maximum output token"))
        self.max_token = QtWidgets.QLineEdit()
        self.max_token.setMinimumSize(QtCore.QSize(0, 35))
        self.max_token.setObjectName("max_token")

        h_token.addWidget(label_token)
        h_token.addWidget(self.max_token)
        v1.addLayout(h_token)

        h_model = QtWidgets.QHBoxLayout()
        self.label_selectmodel = QtWidgets.QLabel()
        self.label_selectmodel.setObjectName("label_selectmodel")
        self.label_selectmodel.setText(tr('Text  Or Srt  Translation')+tr("Model"))
        self.openllm_model = QtWidgets.QComboBox()
        self.openllm_model.setMinimumSize(QtCore.QSize(0, 35))
        self.openllm_model.setObjectName("openllm_model")
        h_model.addWidget(self.label_selectmodel)
        h_model.addWidget(self.openllm_model)
        v1.addLayout(h_model)

        self.label_allmodels = QtWidgets.QLabel()
        self.label_allmodels.setObjectName("label_allmodels")
        self.label_allmodels.setText(
            tr("Fill in all available models, separated by commas. After filling in, you can select them above"))
        v1.addWidget(self.label_allmodels)

        self.edit_allmodels = QtWidgets.QPlainTextEdit()
        self.edit_allmodels.setObjectName("edit_allmodels")
        v1.addWidget(self.edit_allmodels)

        self.label_4 = QtWidgets.QLabel()
        self.label_4.setObjectName("label_4")

        self.template = QtWidgets.QPlainTextEdit()
        self.template.setObjectName("template")
        self.template.setReadOnly(True)
        v1.addWidget(self.label_4)
        v1.addWidget(self.template)

        self.set = QtWidgets.QPushButton()
        self.set.setMinimumSize(QtCore.QSize(0, 35))
        self.set.setObjectName("set")

        self.test = QtWidgets.QPushButton()
        self.test.setMinimumSize(QtCore.QSize(0, 30))
        self.test.setObjectName("test")
        self.test.setText(tr("Test"))

        help_btn = QtWidgets.QPushButton()
        help_btn.setMinimumSize(QtCore.QSize(0, 35))
        help_btn.setStyleSheet("background-color: rgba(255, 255, 255,0)")
        help_btn.setObjectName("help_btn")
        help_btn.setCursor(Qt.PointingHandCursor)
        help_btn.setText(tr("Get API Key"))
        help_btn.clicked.connect(lambda: open_url(url='https://www.openllm.sh'))

        h4.addWidget(self.set)
        h4.addWidget(self.test)
        h4.addWidget(help_btn)
        v1.addLayout(h4)
        self.template.setPlainText(tr("Prompt: Please open the {} file directly to modify it", 'openllm', 'openllm'))

        self.retranslateUi(form)
        QtCore.QMetaObject.connectSlotsByName(form)

    def update_ui(self):
        allmodels_str = settings.get('openllm_model', '')
        allmodels = str(settings.get('openllm_model', '')).split(',')
        self.openllm_model.clear()
        self.openllm_model.addItems(allmodels)
        self.edit_allmodels.setPlainText(allmodels_str)
        self.openllm_api.setText(str(params.get("openllm_api", '')))
        self.openllm_key.setText(str(params.get("openllm_key", '')))
        self.openllm_model.setCurrentText(params.get("openllm_model", ''))
        self.max_token.setText(str(params.get("openllm_max_token", '')))

    def retranslateUi(self, form):
        form.setWindowTitle("OpenLLM")
        self.label_url.setText(tr("API URL"))
        self.label_3.setText(tr("SK"))
        self.label_4.setText(tr("{lang} represents the target language name, do not delete it."))
        self.set.setText(tr('Save'))
